pub type TrafficLight = enum {
  Red,
  Yellow(duration: Int),
  Green,
} derive[Debug]

fn main() -> Int {
  let r = TrafficLight.Red;
  let y = TrafficLight.Yellow(5);
  let g = TrafficLight.Green;
  io.debug(r);
  io.debug(y);
  io.debug(g);
  match y {
    Yellow(duration) => { return duration; }
    _ => { return 0; }
  }
}
